<!DOCTYPE html>
<html lang="zh-CN" data-theme="light">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>稚园乡小课堂日记</title>
<style>
    @import url('https://fonts.googleapis.com/css2?family=ZCOOL+KuaiLe&display=swap');

    :root {
        --diary-bg: #fff9f0;
        --diary-border: #ffdcb3;
        --text-color: #7d5a3f;
        --title-color: #d98c56;
        --accent-color: #ffb380;
        --shadow-color: rgba(217, 140, 86, 0.1);
        --switch-bg: #f0eada;
        --sun-color: #f39c12;
        --moon-color: #f1c40f;
        --page-btn-bg: #ffe9d1;
        --page-btn-hover-bg: #ffddbf;
        --page-btn-active-bg: #d98c56;
        --page-btn-active-color: #fff;
    }

    html[data-theme='dark'] {
        --diary-bg: #4a423a;
        --diary-border: #6d5d4c;
        --text-color: #d1c8c0;
        --title-color: #e6a77e;
        --accent-color: #c98a62;
        --shadow-color: rgba(0, 0, 0, 0.2);
        --switch-bg: #3c352e;
        --page-btn-bg: #5a4f44;
        --page-btn-hover-bg: #6a5e51;
        --page-btn-active-bg: #e6a77e;
        --page-btn-active-color: #4a423a;
    }

    /* 其余样式与之前版本相同... */
    .diary-container {
        font-family: 'ZCOOL KuaiLe', cursive, sans-serif; width: 100%; max-width: 500px; margin: 20px auto;
        border: 2px dashed var(--diary-border); border-radius: 15px; background-color: var(--diary-bg);
        box-shadow: 0 5px 15px var(--shadow-color); padding: 10px; box-sizing: border-box;
        transition: all 0.3s ease; color: var(--text-color);
    }
    .diary-container details { transition: all 0.3s ease; }
    .diary-container summary {
        display: flex; justify-content: space-between; align-items: center; padding: 10px 15px;
        font-size: 1.5em; color: var(--title-color); cursor: pointer; list-style: none;
        outline: none; user-select: none; position: relative;
    }
    .diary-container summary::-webkit-details-marker { display: none; }
    .diary-container summary::before {
        content: '🎀'; margin-right: 10px; transition: transform 0.3s ease; display: inline-block;
    }
    .diary-container details[open] > summary::before { transform: rotate(90deg); }
    .diary-title { text-shadow: 1px 1px 2px var(--shadow-color); }
    .theme-switch-wrapper { display: flex; align-items: center; }
    .theme-switch { position: relative; display: inline-block; width: 50px; height: 26px; margin-left: 10px; }
    .theme-switch input { opacity: 0; width: 0; height: 0; }
    .slider { position: absolute; cursor: pointer; top: 0; left: 0; right: 0; bottom: 0; background-color: var(--switch-bg); transition: .4s; border-radius: 26px; }
    .slider:before {
        position: absolute; content: "☀️"; height: 18px; width: 18px; left: 4px; bottom: 4px;
        font-size: 14px; line-height: 18px; text-align: center; transition: .4s; color: var(--sun-color);
    }
    input:checked + .slider:before { transform: translateX(24px); content: "🌙"; color: var(--moon-color); }
    /* ...其余旧样式结束 */

    .lessons-content {
        padding: 0 15px 15px;
        border-top: 2px dotted var(--diary-border);
        margin-top: 10px;
    }

    .lesson-item {
        /* [优化-1]: 减小了上边距和行高，使布局更紧凑 */
        margin-top: 10px;
        padding-left: 20px;
        position: relative;
        font-size: 1.1em;
        line-height: 1.5;
    }

    .lesson-item::before {
        content: '🍓'; position: absolute; left: -5px; top: 0px;
    }

    .lesson-day { font-weight: bold; color: var(--accent-color); }

    /* [新增-1]: 分页控件的样式 */
    .pagination-controls {
        display: flex;
        justify-content: center;
        align-items: center;
        padding: 15px 0 5px;
        user-select: none;
    }
    .pagination-controls button {
        font-family: 'ZCOOL KuaiLe', cursive, sans-serif;
        background-color: var(--page-btn-bg);
        color: var(--text-color);
        border: none;
        border-radius: 8px;
        padding: 5px 10px;
        margin: 0 4px;
        cursor: pointer;
        font-size: 1em;
        transition: background-color 0.3s;
    }
    .pagination-controls button:hover {
        background-color: var(--page-btn-hover-bg);
    }
    .pagination-controls button:disabled {
        opacity: 0.5;
        cursor: not-allowed;
    }
    .pagination-controls button.active {
        background-color: var(--page-btn-active-bg);
        color: var(--page-btn-active-color);
        font-weight: bold;
    }

</style>
</head>
<body>

<!--  HTML结构中唯一需要改动的地方，是增加一个用于放置分页控件的容器  -->
<div class="diary-container">
    <template id="lessons-data-source">
$1
    </template>
    <details open>
        <summary>
            <span class="diary-title">稚园乡小课堂</span>
            <div class="theme-switch-wrapper">
                <label class="theme-switch">
                    <input type="checkbox" id="theme-toggle">
                    <span class="slider"></span>
                </label>
            </div>
        </summary>
        <div class="lessons-content" id="lessons-list">
            <!-- 课程列表将由JavaScript动态生成在这里 -->
        </div>
        <!-- [新增-2]: 分页控件的HTML容器 -->
        <div class="pagination-controls" id="pagination-controls">
            <!-- 分页按钮将由JavaScript动态生成在这里 -->
        </div>
    </details>
</div>

<script>
    (function() {
        // [优化-2] 脚本主要逻辑改动
        // 查找元素
        const diaryContainer = document.currentScript.previousElementSibling;
        const lessonsDataSource = diaryContainer.querySelector('#lessons-data-source');
        const lessonsList = diaryContainer.querySelector('#lessons-list');
        const paginationControls = diaryContainer.querySelector('#pagination-controls');
        const themeToggle = diaryContainer.querySelector('#theme-toggle');

        // 从template标签获取原始数据
        const lessonsRaw = lessonsDataSource.innerHTML;
        const lines = lessonsRaw.trim() ? lessonsRaw.trim().split(/\\n|\n/).filter(line => line.trim() !== '') : [];

        // 分页设置
        const itemsPerPage = 5; // 每页显示5条记录
        let currentPage = 1;
        const totalPages = Math.ceil(lines.length / itemsPerPage);

        // 渲染指定页的课程函数
        function renderLessons(page) {
            currentPage = page;
            const start = (page - 1) * itemsPerPage;
            const end = start + itemsPerPage;
            const pageLines = lines.slice(start, end);

            let htmlContent = '';
            if (pageLines.length > 0) {
                 pageLines.forEach(line => {
                    const parts = line.split(/：|:/);
                    const day = parts.length > 1 ? parts[0].trim() : '';
                    const text = parts.length > 1 ? parts.slice(1).join('：').trim() : line.trim();
                    htmlContent += `<div class="lesson-item"><span class="lesson-day">${day}：</span><span>${text}</span></div>`;
                });
            } else {
                htmlContent = `<div class="lesson-item">还没有上课记录哦~</div>`;
            }
            lessonsList.innerHTML = htmlContent;
            renderPagination(); // 每次渲染课程后都重新渲染分页控件
        }

        // 渲染分页控件函数
        function renderPagination() {
            if (totalPages <= 1) {
                paginationControls.innerHTML = '';
                return;
            }

            let paginationHTML = `
                <button id="prev-page" ${currentPage === 1 ? 'disabled' : ''}>上一页</button>
            `;

            for (let i = 1; i <= totalPages; i++) {
                paginationHTML += `<button class="page-num ${i === currentPage ? 'active' : ''}" data-page="${i}">${i}</button>`;
            }

            paginationHTML += `
                <button id="next-page" ${currentPage === totalPages ? 'disabled' : ''}>下一页</button>
            `;
            paginationControls.innerHTML = paginationHTML;
        }

        // 添加分页事件监听
        paginationControls.addEventListener('click', function(e) {
            const target = e.target;
            if (target.id === 'prev-page' && currentPage > 1) {
                renderLessons(currentPage - 1);
            } else if (target.id === 'next-page' && currentPage < totalPages) {
                renderLessons(currentPage + 1);
            } else if (target.classList.contains('page-num')) {
                const page = parseInt(target.dataset.page, 10);
                renderLessons(page);
            }
        });

        // 初始化：渲染第一页
        renderLessons(1);

        // 主题切换逻辑 (与之前版本相同)
        const initTheme = () => {
            const currentTheme = localStorage.getItem('theme') || 'light';
            document.documentElement.setAttribute('data-theme', currentTheme);
            if (themeToggle) themeToggle.checked = currentTheme === 'dark';
        };
        if(themeToggle){
            themeToggle.addEventListener('change', function() {
                const theme = this.checked ? 'dark' : 'light';
                document.documentElement.setAttribute('data-theme', theme);
                localStorage.setItem('theme', theme);
            });
        }
        initTheme();

    })();
</script>

</body>
</html>
